// Every created app carries the AI instruction files of its starter (generated by libs/mcp/ai/sync.ts): AGENTS.md and
// CLAUDE.md with the same text, portable Codex/Cursor and Claude Code skill bundles, Cursor rules, Copilot instructions.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { expect, test } from "vitest";
import { TEMPLATES, templateFiles } from "../index.ts";

const templates = resolve(import.meta.dirname, "../../../templates");

test.each(TEMPLATES.map((template) => [template.id, template.dir] as const))("%s: AI instruction files are copied", (_id, dir) => {
  const files = new Map(templateFiles(resolve(templates, dir)).map((file) => [file.path.split("\\").join("/"), file.source]));
  for (const path of ["AGENTS.md", "CLAUDE.md", ".github/copilot-instructions.md", ".cursor/rules/rivet.mdc", ".claude/skills/rivet-add-route/SKILL.md"])
    expect(files.has(path), path).toBe(true);
  for (const agent of [".agents", ".claude"]) {
    for (const path of [
      "SKILL.md",
      "LICENSE.txt",
      "references/visual-foundations.md",
      "references/structure-and-layout.md",
      "references/component-composition.md",
      "references/interactions.md",
      "references/rivet-implementation.md",
    ])
      expect(files.has(`${agent}/skills/rivet-ui-design/${path}`), `${agent}: ${path}`).toBe(true);
  }
  expect(readFileSync(files.get("AGENTS.md")!, "utf8")).toBe(readFileSync(files.get("CLAUDE.md")!, "utf8"));
});
